public static class QualityErrors{public static Error Invalid=>Error.Validation("qc.invalid_data");public static Error NotFound=>Error.NotFound("qc.resource.not_found");public static Error Concurrency=>Error.Concurrency("qc.concurrency_conflict");public static Error InvalidTransition=>Error.BusinessRule("qc.invalid_transition");public static Error ReasonRequired=>Error.Validation("qc.reason_required");public static Error CriteriaIncomplete=>Error.BusinessRule("qc.criteria_incomplete");public static Error TypeMismatch=>Error.Validation("qc.result_type_mismatch");public static Error BlockingDefect=>Error.BusinessRule("qc.blocking_defect");public static Error ReproductionNotAllowed=>Error.BusinessRule("qc.reproduction_not_allowed");}
public static class QualityText{public static string? Code(string?x,int max=80){if(string.IsNullOrWhiteSpace(x))return null;string s=x.Trim().ToUpperInvariant();return s.Length<=max&&s.All(c=>char.IsAsciiLetterOrDigit(c)||c is '_' or '-' or '.')?s:null;}public static string? Text(string?x,int max,bool optional=false){if(string.IsNullOrWhiteSpace(x))return optional?null:null;string s=x.Trim();return s.Length<=max?s:null;}}
public sealed class QCChecklistTemplate{private QCChecklistTemplate(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public string Code{get;private set;}="";public string Name{get;private set;}="";public ProductionJobType? ApplicableJobType{get;private set;}public string? ProductTypeCode{get;private set;}public bool IsActive{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static Result<QCChecklistTemplate>Create(Guid company,string code,string name,ProductionJobType?job,string?productType,DateTimeOffset now){string?c=QualityText.Code(code),n=QualityText.Text(name,200),p=string.IsNullOrWhiteSpace(productType)?null:QualityText.Code(productType,50);if(company==Guid.Empty||c is null||n is null)return Result.Failure<QCChecklistTemplate>(QualityErrors.Invalid);return Result.Success(new QCChecklistTemplate(){Id=Guid.NewGuid(),CompanyId=company,Code=c,Name=n,ApplicableJobType=job,ProductTypeCode=p,IsActive=true,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result SetActive(bool active,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(QualityErrors.Concurrency);IsActive=active;UpdatedAtUtc=now;Version++;return Result.Success();}}
public sealed class QCChecklistCriterion{private QCChecklistCriterion(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid TemplateId{get;private set;}public string Code{get;private set;}="";public string Name{get;private set;}="";public QCCriterionType CriterionType{get;private set;}public bool IsRequired{get;private set;}public int SortOrder{get;private set;}public decimal? MinimumValue{get;private set;}public decimal? MaximumValue{get;private set;}public string? AllowedChoiceCodes{get;private set;}public static Result<QCChecklistCriterion>Create(Guid company,Guid template,string code,string name,QCCriterionType type,bool required,int sort,decimal?min,decimal?max,string?choices){string?c=QualityText.Code(code),n=QualityText.Text(name,200);if(c is null||n is null||sort<0||max<min||(type==QCCriterionType.Choice&&string.IsNullOrWhiteSpace(choices)))return Result.Failure<QCChecklistCriterion>(QualityErrors.Invalid);return Result.Success(new QCChecklistCriterion(){Id=Guid.NewGuid(),CompanyId=company,TemplateId=template,Code=c,Name=n,CriterionType=type,IsRequired=required,SortOrder=sort,MinimumValue=min,MaximumValue=max,AllowedChoiceCodes=choices?.Trim().ToUpperInvariant()});}}
public sealed class QCInspection{private QCInspection(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid OrderId{get;private set;}public Guid OrderItemId{get;private set;}public Guid ProductionJobId{get;private set;}public Guid TemplateId{get;private set;}public long TemplateVersion{get;private set;}public Guid InspectorUserId{get;private set;}public QCInspectionStatus Status{get;private set;}public QCOutcome Outcome{get;private set;}public Guid? ParentInspectionId{get;private set;}public Guid? ReproductionRequestId{get;private set;}public DateTimeOffset? StartedAtUtc{get;private set;}public DateTimeOffset? CompletedAtUtc{get;private set;}public string? DecisionReason{get;private set;}public string? Notes{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static QCInspection Create(Guid company,Guid order,Guid item,Guid job,Guid template,long templateVersion,Guid inspector,Guid?parent,Guid?reproduction,DateTimeOffset now)=>new(){Id=Guid.NewGuid(),CompanyId=company,OrderId=order,OrderItemId=item,ProductionJobId=job,TemplateId=template,TemplateVersion=templateVersion,InspectorUserId=inspector,Status=QCInspectionStatus.InProgress,Outcome=QCOutcome.Pending,ParentInspectionId=parent,ReproductionRequestId=reproduction,StartedAtUtc=now,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1};public Result Suspend(string reason,long expected,DateTimeOffset now)=>Transition(QCInspectionStatus.Suspended,reason,expected,now);public Result Review(string reason,long expected,DateTimeOffset now)=>Transition(QCInspectionStatus.ManagementReview,reason,expected,now);public Result Reject(string reason,long expected,DateTimeOffset now)=>Finalize(QCInspectionStatus.Rejected,QCOutcome.Rejected,reason,expected,now);public Result Approve(long expected,DateTimeOffset now)=>Finalize(QCInspectionStatus.Approved,QCOutcome.Approved,null,expected,now);private Result Transition(QCInspectionStatus target,string reason,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(QualityErrors.Concurrency);string?r=QualityText.Text(reason,500);bool allowed=(Status,target)is(QCInspectionStatus.InProgress,QCInspectionStatus.Suspended)or(QCInspectionStatus.InProgress,QCInspectionStatus.ManagementReview)or(QCInspectionStatus.Suspended,QCInspectionStatus.ManagementReview);if(r is null)return Result.Failure(QualityErrors.ReasonRequired);if(!allowed)return Result.Failure(QualityErrors.InvalidTransition);Status=target;DecisionReason=r;Touch(now);return Result.Success();}private Result Finalize(QCInspectionStatus target,QCOutcome outcome,string?reason,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(QualityErrors.Concurrency);if(target==QCInspectionStatus.Rejected&&QualityText.Text(reason,500)is null)return Result.Failure(QualityErrors.ReasonRequired);if(Status is not(QCInspectionStatus.InProgress or QCInspectionStatus.ManagementReview))return Result.Failure(QualityErrors.InvalidTransition);Status=target;Outcome=outcome;DecisionReason=QualityText.Text(reason,500,true);CompletedAtUtc=now;Touch(now);return Result.Success();}private void Touch(DateTimeOffset now){UpdatedAtUtc=now;Version++;}}
public sealed class QCCriteriaResult{private QCCriteriaResult(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid InspectionId{get;private set;}public Guid TemplateCriterionId{get;private set;}public string CriterionCode{get;private set;}="";public string CriterionName{get;private set;}="";public QCCriterionType CriterionType{get;private set;}public bool IsRequired{get;private set;}public bool? PassFailValue{get;private set;}public decimal? NumericValue{get;private set;}public string? TextValue{get;private set;}public string? ChoiceCode{get;private set;}public DateTimeOffset RecordedAtUtc{get;private set;}public Guid RecordedByUserId{get;private set;}public static Result<QCCriteriaResult>Create(Guid company,Guid inspection,QCChecklistCriterion c,bool?pass,decimal?numeric,string?text,string?choice,Guid actor,DateTimeOffset now){string?tv=QualityText.Text(text,1000,true),cv=string.IsNullOrWhiteSpace(choice)?null:QualityText.Code(choice);bool shape=c.CriterionType switch{QCCriterionType.PassFail=>pass is not null&&numeric is null&&tv is null&&cv is null,QCCriterionType.Numeric=>numeric is not null&&pass is null&&tv is null&&cv is null&&(c.MinimumValue is null||numeric>=c.MinimumValue)&&(c.MaximumValue is null||numeric<=c.MaximumValue),QCCriterionType.Text=>tv is not null&&pass is null&&numeric is null&&cv is null,QCCriterionType.Choice=>cv is not null&&pass is null&&numeric is null&&tv is null&&(c.AllowedChoiceCodes??"").Split(',',StringSplitOptions.TrimEntries).Contains(cv),_=>false};if(!shape)return Result.Failure<QCCriteriaResult>(QualityErrors.TypeMismatch);return Result.Success(new QCCriteriaResult(){Id=Guid.NewGuid(),CompanyId=company,InspectionId=inspection,TemplateCriterionId=c.Id,CriterionCode=c.Code,CriterionName=c.Name,CriterionType=c.CriterionType,IsRequired=c.IsRequired,PassFailValue=pass,NumericValue=numeric,TextValue=tv,ChoiceCode=cv,RecordedAtUtc=now,RecordedByUserId=actor});}}
public sealed class DefectType{private DefectType(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public string Code{get;private set;}="";public string Name{get;private set;}="";public string CategoryCode{get;private set;}="";public DefectSeverity Severity{get;private set;}public bool IsBlocking{get;private set;}public bool IsActive{get;private set;}public DateTimeOffset CreatedAtUtc{get;private set;}public DateTimeOffset UpdatedAtUtc{get;private set;}public long Version{get;private set;}public static Result<DefectType>Create(Guid company,string code,string name,string category,DefectSeverity severity,bool blocking,DateTimeOffset now){string?c=QualityText.Code(code),n=QualityText.Text(name,200),cat=QualityText.Code(category,50);if(c is null||n is null||cat is null)return Result.Failure<DefectType>(QualityErrors.Invalid);return Result.Success(new DefectType(){Id=Guid.NewGuid(),CompanyId=company,Code=c,Name=n,CategoryCode=cat,Severity=severity,IsBlocking=blocking,IsActive=true,CreatedAtUtc=now,UpdatedAtUtc=now,Version=1});}public Result SetActive(bool active,long expected,DateTimeOffset now){if(expected!=Version)return Result.Failure(QualityErrors.Concurrency);IsActive=active;UpdatedAtUtc=now;Version++;return Result.Success();}}
public sealed class QCDefect{private QCDefect(){}public Guid Id{get;private set;}public Guid CompanyId{get;private set;}public Guid InspectionId{get;private set;}public Guid? CriteriaResultId{get;private set;}public Guid DefectTypeId{get;private set;}public decimal Quantity{get;private set;}public DefectSeverity Severity{get;private set;}public string? Notes{get;private set;}public Guid? EvidenceFileVersionId{get;private set;}public Guid RecordedByUserId{get;private set;}public DateTimeOffset RecordedAtUtc{get;private set;}public static Result<QCDefect>Create(Guid company,Guid inspection,Guid?result,Guid type,decimal quantity,DefectSeverity severity,string?notes,Guid?evidence,Guid actor,DateTimeOffset now){string?n=QualityText.Text(notes,1000,true);if(quantity<=0||(!string.IsNullOrWhiteSpace(notes)&&n is null))return Result.Failure<QCDefect>(QualityErrors.Invalid);return Result.Success(new QCDefect(){Id=Guid.NewGuid(),CompanyId=company,InspectionId=inspection,CriteriaResultId=result,DefectTypeId=type,Quantity=quantity,Severity=severity,Notes=n,EvidenceFileVersionId=evidence,RecordedByUserId=actor,RecordedAtUtc=now});}}
